            for (let i = 0; i < 12; i++) {
                const b = qTicket('[data-testid="' + (side === 'buy' ? 'submit-long' : 'submit-short') + '"]');
                if (b && !b.disabled) { ready = true; break; }
                await sleep(80);
            }
            if (!ready) return refuse('Vest keeps the ' + (side === 'buy' ? 'Buy' : 'Sell') + ' button disabled (check size, balance and the form)');
            if (mcDemo()) return 0;
